window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[163]={"id":"163","numero":163,"titre":"Coqueluche","objectifs":[{"id":"163-1","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les caractéristiques épidémiologiques, la transmission de la coqueluche","contenu":"<div class=\"notion-course\"><p>La <span>coqueluche</span> est une <span><span class=\"nc-red nc-bold\">toxi-infection</span> bactérienne aiguë</span>, hautement contagieuse, des voies aériennes. L'agent est <span><span class=\"nc-purple_bg nc-bold\">Bordetella pertussis</span></span> (bacille de <span class=\"nc-red nc-bold\">Bordet-Gengou</span>) — un <span>bacille à Gram négatif</span>, <strong>très fragile</strong> et de <strong><span class=\"nc-blue_bg\">culture</span> difficile</strong>. <span><span class=\"nc-purple_bg\">Bordetella parapertussis</span></span> (&lt; <span>5 %</span> des cas) donne une para-coqueluche de forme <span>moins grave</span>.</p>\n      <table>\n        <thead><tr><th>Paramètre</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr><td>Transmission</td><td><strong><span class=\"nc-blue nc-bold\">Strictement interhumaine</span></strong>, surtout <span><span class=\"nc-green nc-bold\">intra-familiale</span></span> et <span><span class=\"nc-green nc-bold\">intra-collectivité</span></span> ; <span class=\"nc-yellow_bg\">voie aérienne</span> (aérosols, <span><span class=\"nc-yellow nc-bold\">gouttelettes</span></span>)</td></tr>\n          <tr><td>Taux d'attaque</td><td><span>~75 %</span> en cas de <span>contact</span> proche et répété</td></tr>\n          <tr><td><span class=\"nc-blue_bg\">Incubation</span></td><td><span><span class=\"nc-pink_bg\">7 à 21 jours</span></span> (<span>10 j</span> en moyenne)</td></tr>\n          <tr><td><span class=\"nc-green_bg nc-bold\">Contagiosité</span></td><td>Jusqu'à <span>3 semaines</span> après le début des signes sans <span>antibiothérapie</span> ; quasi nulle en <span class=\"nc-green_bg\">phase de convalescence</span></td></tr>\n          <tr><td>Létalité</td><td><span>1 à 3 %</span> chez le <span>nourrisson <span class=\"nc-red nc-bold\">&lt; 6 mois</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Profil <span class=\"nc-yellow_bg\">épidémiologique</span></strong> — la coqueluche est une maladie <span><span class=\"nc-red nc-bold\">cosmopolite</span></span>, dont le visage change selon le niveau de développement :</p>\n      <table>\n        <thead><tr><th></th><th>Pays industrialisés</th><th>Pays en développement</th></tr></thead>\n        <tbody>\n          <tr><td>Couverture vaccinale</td><td><span>Élevée</span> (&gt; <span>90 %</span> chez l'enfant en France)</td><td><span>Faible</span> — épidémies sur fond d'endémie</td></tr>\n          <tr><td>Réservoir</td><td><span><span class=\"nc-pink_bg nc-bold\">Adultes</span></span> et <span><span class=\"nc-pink_bg nc-bold\">personnes âgées</span></span> (protection vaccinale qui décline)</td><td><span><span class=\"nc-pink_bg nc-bold\">Enfants</span></span>, qui ré-immunisent naturellement <span>les</span> <span class=\"nc-pink_bg nc-bold\">adultes</span></td></tr>\n          <tr><td>Population à risque</td><td><span><span class=\"nc-red_bg\">Nourrissons non vaccinés</span></span>, contaminés par <span>les</span> <span class=\"nc-pink_bg nc-bold\">adultes</span></td><td><span>Mortalité</span> infantile élevée (<span class=\"nc-red nc-bold\">malnutrition</span>, complications <span class=\"nc-red nc-bold\">respiratoires</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Immunité non définitive</strong> — la protection s'épuise : <span><span class=\"nc-pink nc-bold\">10-15 ans</span></span> après la maladie, <span><span class=\"nc-pink nc-bold\">5-10 ans</span></span> après la <span>vaccination</span> (retenir <span>5 ans</span> en QCM). <span>Les</span> <span>anticorps maternels</span> ne protègent pas le nourrisson, sauf vaccination pendant la <span>grossesse</span>.</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Le <span>nourrisson non encore vacciné</span> est la cible la plus vulnérable : il se contamine auprès d'un <span>adulte</span> de l'entourage dont l'immunité vaccinale s'est épuisée — c'est toute la logique du <strong>cocooning</strong>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 163</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3525542/fr/choix-et-durees-d-antibiotherapies-coqueluche-chez-le-nourrisson-l-enfant-et-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · coqueluche, antibiothérapie, 2024</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Coqueluche\" target=\"_blank\" rel=\"noopener noreferrer\">Vaccination Info Service · rappels coqueluche 2026</a></li></ul></details>","frequence":1},{"id":"163-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes de la coqueluche","contenu":"<div class=\"notion-course\"><p>La coqueluche est une <span><span class=\"nc-red nc-bold\">toxi-infection</span></span> : <span>Bordetella pertussis</span> sécrète plusieurs <span><span class=\"nc-pink nc-bold\">toxines</span></span> qui agissent sur l'<span><span class=\"nc-purple_bg\">épithélium trachéobronchique</span></span>. La bactérie reste localisée à la muqueuse respiratoire — ce sont ses <strong><span class=\"nc-pink nc-bold\">toxines</span></strong> qui font la maladie.</p>\n      <table>\n        <thead><tr><th>Facteur</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-pink_bg\">Hémagglutinine</span> <span class=\"nc-pink_bg\">filamenteuse</span></span></td><td><strong>Adhésine</strong> : permet l'interaction et la fixation de la bactérie à l'hôte</td></tr>\n          <tr><td><span><span class=\"nc-pink_bg\">Toxine</span> <span class=\"nc-pink_bg\">pertussique</span></span></td><td><span><span class=\"nc-red nc-bold\">Nécrose</span></span> de la muqueuse respiratoire ; <span><span class=\"nc-red nc-bold\">hyperlymphocytose</span></span> ; <span><span class=\"nc-red nc-bold\">hypersensibilité à l'histamine</span></span> ; tropisme neurologique</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"nc-purple nc-bold\">La </span><span><span class=\"nc-purple nc-bold\">toxine pertussique</span></span> stimule <span class=\"nc-red_bg\">la </span><strong><span class=\"nc-red_bg\">prolifération lymphocytaire</span></strong> : <span class=\"nc-red nc-bold\">l'</span><span><span class=\"nc-red nc-bold\">hyperlymphocytose</span></span> est donc évocatrice du diagnostic. Au-delà de <span>50 000/mm³</span>, elle devient un <span>critère de <span class=\"nc-red nc-bold\">gravité</span></span> qui <strong><span class=\"nc-red_bg nc-bold\">anticipe l'aggravation respiratoire</span></strong> (coqueluche maligne).</p>\n      <p>Après le <span>21ᵉ jour</span>, la bactérie a disparu mais <span>les</span> <span>symptômes persistent</span> : c'est le <strong>phénomène toxinique</strong> et l'<span>hyperréactivité bronchique</span> qui entretiennent la <span>toux</span>, alors que les prélèvements microbiologiques sont déjà négatifs.</p>\n      <div class=\"callout callout-info\"><strong>Conséquence pratique.</strong> Parce que la maladie est <span>toxinique</span>, l'<span>antibiothérapie</span> tardive n'agit plus sur <span>les</span> symptômes : elle ne fait que <span><span class=\"nc-green_bg\">réduire la</span> <span class=\"nc-green_bg nc-bold\">contagiosité</span></span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 163</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3525542/fr/choix-et-durees-d-antibiotherapies-coqueluche-chez-le-nourrisson-l-enfant-et-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · coqueluche, antibiothérapie, 2024</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Coqueluche\" target=\"_blank\" rel=\"noopener noreferrer\">Vaccination Info Service · rappels coqueluche 2026</a></li></ul></details>","frequence":0},{"id":"163-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic de la coqueluche","contenu":"<div class=\"notion-course\"><p>Le diagnostic de coqueluche est avant tout <span>clinique</span>. La forme typique du <strong>grand enfant non vacciné</strong> évolue en <span><span class=\"nc-red nc-bold\">4 phases</span></span> successives :</p>\n      <table>\n        <thead><tr><th>Phase</th><th>Durée</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Incubation</td><td><span>7-21 j</span></td><td>Cliniquement <span>silencieuse</span></td></tr>\n          <tr><td><span class=\"nc-green nc-bold\">Catarrhale</span></td><td><span>7-15 j</span></td><td><strong><span class=\"nc-green_bg nc-bold\">Contagiosité</span> maximale</strong> ; <span><span class=\"nc-brown_bg\">fièvre absente</span></span> ou modérée ; <span>toux</span> d'abord banale avec <span class=\"nc-green_bg\">rhinorrhée</span>, puis tenace et quinteuse</td></tr>\n          <tr><td><span class=\"nc-red nc-bold\">Quintes</span> (phase d'état)</td><td><span>3-6 sem</span></td><td><span><span class=\"nc-brown_bg\">Sans fièvre</span></span> ; <span class=\"nc-red nc-bold\">quintes</span> de <span>toux</span> violentes <span class=\"nc-red_bg\">sans inspiration efficace</span>, <span><span class=\"nc-blue_bg\">congestion du visage</span></span><span class=\"nc-blue_bg\"> voire </span><span><span class=\"nc-blue_bg\">cyanose</span></span>, <span><span class=\"nc-green_bg\">reprise inspiratoire sonore</span></span> (« chant du coq ») ; <span>toux</span> <span><span class=\"nc-yellow_bg\">émétisante</span></span>, à prédominance <span><span class=\"nc-red nc-bold\">nocturne</span></span> ; déclenchée par <span class=\"nc-red nc-bold\">déglutition</span>, <span class=\"nc-red nc-bold\">cris</span>, <span class=\"nc-red nc-bold\">effort</span></td></tr>\n          <tr><td>Convalescence</td><td><span>~<span class=\"nc-pink nc-bold\">6 mois</span></span></td><td>Régression progressive des <span class=\"nc-red nc-bold\">quintes</span> ; <span>hyperréactivité bronchique résiduelle</span> ; <span><span class=\"nc-blue_bg\">asthénie</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Formes selon le <span>terrain</span></strong> — l'expression varie fortement avec l'âge et l'immunité résiduelle :</p>\n      <table>\n        <thead><tr><th>Terrain</th><th>Particularités cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><span>Nourrisson</span></td><td><span class=\"nc-blue\">Quintes </span><span><span class=\"nc-blue\">asphyxiantes</span></span> ; la <strong><span class=\"nc-green_bg\">reprise inspiratoire sonore</span> <span class=\"nc-red_bg nc-bold\">manque</span></strong> généralement avant <span>3 <span class=\"nc-pink\">mois</span></span> ; <span><span class=\"nc-red nc-bold\">apnées</span> ± <span class=\"nc-red nc-bold\">bradycardies</span></span>, <span class=\"nc-blue\">accès de </span><span><span class=\"nc-blue\">cyanose</span></span> ; à évoquer devant toute <span>toux</span> quinteuse d'un nourrisson non vacciné</td></tr>\n          <tr><td>Adolescent / adulte</td><td><span><span class=\"nc-red nc-bold\">Toux sans fièvre</span></span> persistant <span><span class=\"nc-red nc-bold\">≥ 1 semaine</span></span>, à recrudescence <span><span class=\"nc-red nc-bold\">nocturne</span> et <span class=\"nc-red nc-bold\">insomniante</span></span> ; notion de <span class=\"nc-blue_bg\">contage</span> et d'<span class=\"nc-blue_bg\">incubation</span> longue</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Dogme EDN.</strong> Une <span>toux <span class=\"nc-red nc-bold\">en l'absence de fièvre</span></span>, prolongée <span><span class=\"nc-red nc-bold\">≥ 1 semaine</span></span>, chez un sujet <strong><span class=\"nc-red nc-bold\">non couvert par la </span><span><span class=\"nc-red nc-bold\">vaccination</span></span></strong> → évoquer la coqueluche. Signes d'appel associés : <span>toux</span> <span><span class=\"nc-yellow_bg\">émétisante</span></span>, recrudescence <span><span class=\"nc-red nc-bold\">nocturne</span></span>, <span><span class=\"nc-blue_bg\">contage</span></span> identifié.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 163</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3525542/fr/choix-et-durees-d-antibiotherapies-coqueluche-chez-le-nourrisson-l-enfant-et-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · coqueluche, antibiothérapie, 2024</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Coqueluche\" target=\"_blank\" rel=\"noopener noreferrer\">Vaccination Info Service · rappels coqueluche 2026</a></li></ul></details>","frequence":2},{"id":"163-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les diagnostics différentiels de la coqueluche","contenu":"<div class=\"notion-course\"><p><span>Les</span> diagnostics différentiels sont les autres causes de <span>toux subaiguë non fébrile</span>, à classer par mécanisme :</p>\n      <table>\n        <thead><tr><th>Mécanisme</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><span>Infectieux</span></td><td><span>Mycoplasma pneumoniae</span> ; <span>Chlamydia pneumoniae</span> ; <span>grippe</span> ; <span>tuberculose</span></td></tr>\n          <tr><td>ORL</td><td><span>Sinusite chronique</span> avec rhinorrhée postérieure</td></tr>\n          <tr><td>Pneumo-allergologique</td><td><span>Asthme</span> ; <span>allergie</span> ; <span>pneumopathie interstitielle diffuse</span></td></tr>\n          <tr><td>Mécanique</td><td><span>RGO</span> ; tumeur ; compression trachéale ; <span>corps étranger</span></td></tr>\n          <tr><td><span>Iatrogène</span></td><td><span>IEC</span> ; <span>bêta-bloquants</span> (également ARA II, <span>gliptines</span>)</td></tr>\n          <tr><td>Psychogène</td><td><span>Toux</span> psychogène (diagnostic d'élimination)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> Une <span>fièvre</span> n'appartient pas au tableau d'une coqueluche non compliquée : sa présence doit faire reconsidérer le diagnostic ou évoquer une <span>surinfection</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 204 — <span>Toux</span> · 159 — <span>Tuberculose</span> Enfant / Adulte · 188 — <span>Asthme</span> - Rhinite</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 163</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3525542/fr/choix-et-durees-d-antibiotherapies-coqueluche-chez-le-nourrisson-l-enfant-et-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · coqueluche, antibiothérapie, 2024</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Coqueluche\" target=\"_blank\" rel=\"noopener noreferrer\">Vaccination Info Service · rappels coqueluche 2026</a></li></ul></details>","frequence":0},{"id":"163-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités du diagnostic microbiologique","contenu":"<div class=\"notion-course\"><p><strong>Examens non spécifiques</strong> — ils orientent sans confirmer :</p>\n      <ul>\n        <li><span>NFS</span> : <span><span class=\"nc-blue_bg\">hyperlymphocytose</span></span> (souvent &gt; <span>10 G/L</span>), inconstante dans <span>les</span> formes sans gravité.</li>\n        <li><span>Radiographie thoracique</span> : <span><span class=\"nc-green_bg nc-bold\">normale</span></span> ou simple <span class=\"nc-green_bg nc-bold\">syndrome bronchique</span> — réalisée surtout pour éliminer un <span>diagnostic différentiel</span>.</li>\n        <li><span>Pas de syndrome inflammatoire</span> <span>biologique</span>.</li>\n      </ul>\n      <p><strong>Confirmation microbiologique</strong> — sur <span>aspiration</span> ou <span>écouvillonnage nasopharyngé</span> (ou recueil de mucus de quinte) :</p>\n      <table>\n        <thead><tr><th>Technique</th><th>Performances</th><th>Place</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-blue_bg\">PCR Bordetella</span></span></td><td><strong><span class=\"nc-red nc-bold\">Référence</span></strong> : <span>90 %</span> de sensibilité, <span>99 %</span> de spécificité ; maximale la 1ʳᵉ semaine ; résultat en <span><span class=\"nc-pink nc-bold\">24 h</span></span></td><td>Examen de 1ʳᵉ intention</td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">Culture</span></span> (milieux <span><span class=\"nc-red nc-bold\">Bordet-Gengou</span></span> ou <span>Regan-Lowe</span>)</td><td>Spécificité <span>100 %</span> mais sensibilité <span>faible</span> ; à réaliser &lt; <span>15 j</span> ; résultat en 3-7 j</td><td>Surtout <span><span class=\"nc-blue nc-bold\">surveillance</span></span><span class=\"nc-blue nc-bold\"> épidémiologique</span> des souches</td></tr>\n          <tr><td><span>Sérologie</span></td><td>Sensibilité et spécificité insuffisantes</td><td><span>Non recommandée en France</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Choix de la technique selon le délai</strong> depuis le début des symptômes :</p>\n      <table>\n        <thead><tr><th>Délai</th><th>Inoculum <span>bactérien</span></th><th>Technique</th></tr></thead>\n        <tbody>\n          <tr><td>&lt; <span>15 jours</span></td><td>Élevé</td><td><span>PCR + culture</span> rentables</td></tr>\n          <tr><td><span>15-21 jours</span></td><td>Faible</td><td><span>PCR</span> uniquement</td></tr>\n          <tr><td>&gt; <span>21 jours</span></td><td>Bactéries disparues</td><td>Diagnostic <span>clinique</span> ; tests négatifs sur le cas index, <span>PCR/culture</span> encore utiles chez un cas <span>contact</span> récent</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span>négativation des prélèvements à J21</span> explique que l'<span>isolement</span> soit levé à cette date en l'absence d'<span>antibiothérapie</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 163</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3525542/fr/choix-et-durees-d-antibiotherapies-coqueluche-chez-le-nourrisson-l-enfant-et-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · coqueluche, antibiothérapie, 2024</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Coqueluche\" target=\"_blank\" rel=\"noopener noreferrer\">Vaccination Info Service · rappels coqueluche 2026</a></li></ul></details>","frequence":1},{"id":"163-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prescription de l’antibiothérapie","contenu":"<div class=\"notion-course\"><p>L'<span>antibiothérapie</span> a un <span>objectif double</span> : <strong><span class=\"nc-green_bg\">réduire la</span> <span class=\"nc-green_bg nc-bold\">contagiosité</span></strong> et <strong>écourter <span>les</span> symptômes</strong> — ce dernier effet uniquement si elle est débutée <span>précocement</span>, à la phase <span><span class=\"nc-red nc-bold\">catarrhale</span></span> (<span class=\"nc-pink_bg\">&lt;</span><span><span class=\"nc-pink_bg\"> 3 semaines</span></span>). Débutée à la phase de <span class=\"nc-red\">quintes</span>, elle est <span>inefficace sur les symptômes</span> et ne sert plus qu'à couper la <span class=\"nc-green_bg nc-bold\">contagiosité</span>.</p>\n      <table>\n        <thead><tr><th>Intention</th><th>Molécule</th><th>Durée</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ʳᵉ intention</strong></td><td><span>Macrolides</span> : <span>azithromycine</span> ou <span>clarithromycine</span></td><td><span>Azithromycine</span> <span>3 j</span> ; <span>clarithromycine</span> <span>7 j</span></td></tr>\n          <tr><td><strong>2ᵉ intention</strong> (CI / <span>allergie</span> aux macrolides)</td><td><span><span class=\"nc-pink_bg\">Cotrimoxazole</span></span></td><td><span>7 j</span></td></tr>\n        </tbody>\n      </table>\n      <p><span>Azithromycine</span> et <span>clarithromycine</span> sont utilisables pendant la <strong><span>grossesse</span></strong> (quel qu'en soit le terme) et l'<strong><span>allaitement</span></strong>.</p>\n      <div class=\"callout callout-danger\"><strong>Pièges thérapeutiques.</strong><br><span>Bêta-lactamines</span> : <span>inefficaces</span> sur Bordetella pertussis.<br><span>Antitussifs et fluidifiants bronchiques</span> : <span>contre-indiqués chez le nourrisson</span>, et globalement <span>à proscrire</span> dans <span>les</span> infections respiratoires.<br><span>Kinésithérapie respiratoire</span> : non indiquée à la phase des <span class=\"nc-red\">quintes</span>.</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-red nc-bold\">Référence</span> HAS 2024 : clarithromycine privilégiée pour limiter l’impact écologique, azithromycine alternative. Choisir dose et durée selon âge ; nourrisson de moins de trois mois : évaluation hospitalière. Vérifier interactions, QT, grossesse et RCP plutôt que déclarer toute molécule interchangeable.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 163</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3525542/fr/choix-et-durees-d-antibiotherapies-coqueluche-chez-le-nourrisson-l-enfant-et-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · coqueluche, antibiothérapie, 2024</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Coqueluche\" target=\"_blank\" rel=\"noopener noreferrer\">Vaccination Info Service · rappels coqueluche 2026</a></li></ul></details>","frequence":2},{"id":"163-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les règles d’éviction de l’entourage et de la collectivité","contenu":"<div class=\"notion-course\"><p>L'<span>éviction</span> vise à interrompre la transmission. En ambulatoire : <strong>éviction obl<span>iga</span>toire de la collectivité</strong>. En <span>hospitalisation</span> : précautions <span>« <span class=\"nc-green_bg\">gouttelettes</span> »</span> (chambre individuelle, masque chirurgical).</p>\n      <table>\n        <thead><tr><th>Situation</th><th>Durée d'éviction</th></tr></thead>\n        <tbody>\n          <tr><td>Sans <span>antibiothérapie</span></td><td><span>21 jours</span></td></tr>\n          <tr><td>Sous <span>clarithromycine</span> ou <span><span class=\"nc-pink_bg\">cotrimoxazole</span></span></td><td><span><span class=\"nc-pink nc-bold\">5 jours</span></span></td></tr>\n          <tr><td>Sous <span>azithromycine</span></td><td><span><span class=\"nc-pink nc-bold\">3 jours</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span>Antibioprophylaxie</span> des sujets contacts</strong> — même schéma que l'<span>antibiothérapie</span> curative, le plus précocement possible et au plus tard <span>&lt; 21 j</span> après le dernier contage. Elle ne concerne que <span>les</span> <strong>sujets non protégés par la <span>vaccination</span></strong> :</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Sujets concernés</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-red_bg\">Contacts proches non vaccinés</span></td><td>Personnes vivant sous le même toit ; enfants et personnels de crèche</td></tr>\n          <tr><td><span class=\"nc-red_bg\">Contacts occasionnels « à risque »</span></td><td><span><span class=\"nc-red_bg\">Immunodéprimés</span></span> ; <span class=\"nc-red_bg\">maladies respiratoires chroniques</span> (<span>asthme</span>, <span>BPCO</span>) ; <span>nourrissons non/incomplètement vaccinés</span> ; <span><span class=\"nc-red_bg\">femmes enceintes</span></span> ; <span class=\"nc-red_bg\">entourage de nourrissons non encore vaccinés</span></td></tr>\n        </tbody>\n      </table>\n      <p>Sont au contraire considérés <span>protégés</span> (pas d'<span>antibioprophylaxie</span>) : <span class=\"nc-pink_bg nc-bold\">enfants</span> ≤ <span>11 mois</span> ayant reçu <span>2 doses</span>, <span class=\"nc-pink_bg nc-bold\">enfants</span> &gt;<span> 11 mois</span> ayant reçu <span>3 doses</span> dont la dernière <span class=\"nc-green_bg\">&lt; </span><span><span class=\"nc-green_bg\">5 ans</span></span>, <span class=\"nc-green_bg\">adolescents et adultes dont la dernière dose remonte à &lt; </span><span><span class=\"nc-green_bg\">5 ans</span></span>.</p>\n      <div class=\"callout callout-info\"><strong>En <span>complément</span>.</strong> Un <strong><span class=\"nc-blue_bg nc-bold\">rattrapage vaccinal</span></strong> est proposé à l'entourage non protégé : la <span>vaccination</span> après <span class=\"nc-blue_bg\">contage</span> ne prévient pas la maladie chez le sujet exposé (délai trop court) mais limite la <span>diffusion</span> ultérieure de la bactérie dans la communauté.</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Évaluer prophylaxie selon proximité, délai, protection et vulnérabilité, particulièrement nourrisson/entourage. Le délai depuis le dernier contact et les recommandations en contexte épidémique priment sur une règle simplifiée « uniquement non-vaccinés ».</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 163</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3525542/fr/choix-et-durees-d-antibiotherapies-coqueluche-chez-le-nourrisson-l-enfant-et-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · coqueluche, antibiothérapie, 2024</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Coqueluche\" target=\"_blank\" rel=\"noopener noreferrer\">Vaccination Info Service · rappels coqueluche 2026</a></li></ul></details>","frequence":3},{"id":"163-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de notification","contenu":"<div class=\"notion-course\"><p>La coqueluche <span>n'est pas une maladie à déclaration obligatoire</span>. En revanche, la survenue de <strong>cas groupés</strong> impose une notification :</p>\n      <table>\n        <thead><tr><th>Cadre d'apparition</th><th>Notification requise</th></tr></thead>\n        <tbody>\n          <tr><td>En collectivité (crèche, école)</td><td><span>≥ 2 cas groupés</span> → médecin inspecteur de santé publique de l'<span><span class=\"nc-red nc-bold\">ARS</span></span></td></tr>\n          <tr><td>À l'hôpital / maternité / EHPAD</td><td><span>≥ 2 cas groupés</span> → <span><span class=\"nc-red nc-bold\">CLIN</span></span> <strong>et</strong> médecin inspecteur de santé publique de l'<span><span class=\"nc-red nc-bold\">ARS</span></span></td></tr>\n          <tr><td>Déclaration obl<span>iga</span>toire ?</td><td><span>Non</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège QCM.</strong> Cocher « déclaration obl<span>iga</span>toire » pour la coqueluche est <span>faux</span> — seule existe la <strong>notification des cas groupés</strong> (<span><span class=\"nc-red nc-bold\">ARS</span></span> ± <span class=\"nc-red nc-bold\">CLIN</span>).</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 163</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3525542/fr/choix-et-durees-d-antibiotherapies-coqueluche-chez-le-nourrisson-l-enfant-et-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · coqueluche, antibiothérapie, 2024</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Coqueluche\" target=\"_blank\" rel=\"noopener noreferrer\">Vaccination Info Service · rappels coqueluche 2026</a></li></ul></details>","frequence":0},{"id":"163-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les recommandations vaccinales","contenu":"<div class=\"notion-course\"><ul><li>Vaccin acellulaire combiné : 2, 4, 11 mois, rappels à 6 ans et 11–13 ans. En 2026, rappels dTcaP à 25, 45, 65 ans puis tous les dix ans : la valence coqueluche est systématiquement associée aux rappels DTP en raison de l’indisponibilité du dTP seul.</li><li>Vaccination à chaque grossesse dès le deuxième trimestre, préférentiellement 20–36 SA, pour protéger le nourrisson par anticorps maternels.</li><li>Si vaccination maternelle absente ou trop proche de la naissance, cocooning de l’entourage selon calendrier. Les recommandations renforcées depuis 2024 concernent aussi les professionnels au contact de jeunes nourrissons ; vérifier le délai depuis le dernier rappel.</li><li>Ne pas appliquer une fréquence universelle « tous les dix ans » à toute situation de cocooning. Vacciner après exposition ne remplace pas l’antibioprophylaxie lorsqu’elle est indiquée.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 163</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3525542/fr/choix-et-durees-d-antibiotherapies-coqueluche-chez-le-nourrisson-l-enfant-et-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · coqueluche, antibiothérapie, 2024</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Coqueluche\" target=\"_blank\" rel=\"noopener noreferrer\">Vaccination Info Service · rappels coqueluche 2026</a></li></ul></details>","frequence":3},{"id":"163-10","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les modalités du dépistage des complications de la coqueluche","contenu":"<div class=\"notion-course\"><p><strong>Critères d'<span>hospitalisation</span></strong> : âge <span><span class=\"nc-pink nc-bold\">&lt; 3 mois</span></span> (toute suspicion) ; signes cliniques de <span class=\"nc-red nc-bold\">gravité</span> quel que soit l'âge (<span class=\"nc-yellow_bg\">unité de </span><span><span class=\"nc-yellow_bg\">surveillance</span></span><span class=\"nc-yellow_bg\"> continue</span> ou <span>réanimation</span>) ; formes malignes (réanimation).</p>\n      <p><strong>Complications du nourrisson</strong> (surtout &lt;<span> 3 mois</span>) :</p>\n      <table>\n        <thead><tr><th>Complication</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span>Coqueluche maligne</span></td><td>Responsable de la majorité des décès : <span><span class=\"nc-blue_bg\">hyperlymphocytose majeure</span></span> &gt; <span>50 000/mm³</span>, <span>insuffisance respiratoire</span> / <span class=\"nc-red_bg\">hypoxie réfractaire</span> (<span>SDRA</span>), <span><span class=\"nc-red_bg\">tachycardie</span></span> <span class=\"nc-pink nc-bold\">&gt; </span><span><span class=\"nc-pink nc-bold\">200/min</span></span>, <span><span class=\"nc-red_bg\">défaillance</span></span><span class=\"nc-red_bg\"> multiviscérale</span> → <span>réanimation</span>, <span class=\"nc-pink_bg\">échanges transfusionnels</span> voire <span><span class=\"nc-pink_bg\">ECMO</span></span></td></tr>\n          <tr><td><span>Encéphalopathie coquelucheuse</span></td><td>Exceptionnelle mais très sévère (1/3 décès, 1/3 <span class=\"nc-orange_bg\">séquelles</span>, 1/<span <span=\"\">&gt;3</span> guérison) : <span><span class=\"nc-orange_bg\">état de mal</span></span><span class=\"nc-orange_bg\"> convulsif</span>, troubles <span class=\"nc-blue_bg\">moteurs</span> et <span class=\"nc-blue_bg\">sensoriels</span></td></tr>\n          <tr><td>Respiratoires</td><td><span class=\"nc-orange_bg\">Broncho-pneumopathie</span> (surinfection) ; <span><span class=\"nc-red nc-bold\">atélectasie</span></span> ; <span><span class=\"nc-red nc-bold\">pneumothorax</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Complications de l'adolescent et de l'adulte</strong> :</p>\n      <table>\n        <thead><tr><th>Type</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td>Infectieuses</td><td><span class=\"nc-red nc-bold\">Surinfection </span><span><span class=\"nc-red nc-bold\">bactérienne</span></span> ou virale (otite, sinusite, <span>pneumonie</span>) — à suspecter si <span>fièvre</span></td></tr>\n          <tr><td>Neurologiques</td><td><span><span class=\"nc-red_bg\">Convulsions</span></span>, encéphalopathie (très rares)</td></tr>\n          <tr><td>Mécaniques</td><td><span><span class=\"nc-orange_bg\">Fractures de côtes</span></span> ; <span><span class=\"nc-blue_bg\">hémorragies sous-conjonctivales</span></span> ; <span><span class=\"nc-red_bg\">pneumothorax</span></span> ; <span class=\"nc-red_bg\">emphysème médiastinal</span> ; <span class=\"nc-blue_bg\">hernie</span> ; <span><span class=\"nc-blue_bg\">incontinence urinaire</span></span><span class=\"nc-blue_bg\"> transitoire</span> ; <span class=\"nc-blue_bg\">prolapsus</span></td></tr>\n          <tr><td>Générales</td><td><span class=\"nc-orange_bg\">Dénutrition</span> et <span><span class=\"nc-orange_bg\">déshydratation</span></span> (<span><span class=\"nc-blue\">vomissements</span></span>) ; <span><span class=\"nc-red_bg\">décompensation</span></span><span class=\"nc-red_bg\"> de </span><span><span class=\"nc-red_bg\">comorbidités</span></span> (<span>diabète</span>, <span>insuffisance respiratoire</span> ou cardiaque)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Signe d'alarme.</strong> Chez le nourrisson, une <span>hyperlymphocytose &gt; 50 000/mm³</span> <span>annonce</span> la <span>coqueluche maligne</span> et impose le transfert en <span>réanimation</span> <strong>avant</strong> l'aggravation respiratoire.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 163</a></li><li><a href=\"https://sante.gouv.fr/prevention-en-sante/preserver-sa-sante/vaccination/calendrier-vaccinal\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · calendrier vaccinal 2026</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3525542/fr/choix-et-durees-d-antibiotherapies-coqueluche-chez-le-nourrisson-l-enfant-et-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · coqueluche, antibiothérapie, 2024</a></li><li><a href=\"https://professionnels.vaccination-info-service.fr/Maladies-et-leurs-vaccins/Coqueluche\" target=\"_blank\" rel=\"noopener noreferrer\">Vaccination Info Service · rappels coqueluche 2026</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Fenêtre antibiotique :</strong> débuter le <span class=\"kw-ttt\">macrolide</span> le plus précocement possible, au plus tard <span class=\"kw-chiffre\">&lt; 21 j</span> après le dernier contage.</p><p><strong>Effet sur <span class=\"kw-clinique\">les</span> symptômes :</strong> obtenu uniquement si l’ATB est débutée à la phase <span class=\"kw-clinique\">catarrhale</span> (<span class=\"kw-chiffre\">&lt; 3 semaines</span>) ; débutée à la phase de quintes, elle ne réduit plus que la <span class=\"kw-clinique\">contagiosité</span>.</p><p><strong>Nourrisson &lt;<span class=\"kw-chiffre\"> 3 mois</span> :</strong> <span class=\"kw-alerte\">hospitalisation</span> devant toute suspicion de coqueluche.</p><p><strong>Signal de <span class=\"kw-alerte\">réanimation</span> :</strong> une <span class=\"kw-bio\">hyperlymphocytose</span> &gt; <span class=\"kw-chiffre\">50 000/mm³</span> impose le transfert en <span class=\"kw-ttt\">réanimation</span> avant l’aggravation respiratoire.</p>","hospit":"<p><strong>Pédiatrie :</strong> tout <span class=\"kw-alerte\">nourrisson &lt; 3 mois</span> avec suspicion de coqueluche.</p><p><strong>USC / <span class=\"kw-alerte\">réanimation</span> :</strong> <span class=\"kw-alerte\">signes cliniques de gravité</span>, quel que soit l’âge.</p><p><strong>Réanimation :</strong> <span class=\"kw-alerte\">forme maligne</span> (peut nécessiter <span class=\"kw-ttt\">échanges transfusionnels</span>, voire <span class=\"kw-ttt\">ECMO</span>).</p><p><strong>Ambulatoire :</strong> formes non compliquées du grand enfant et de l’adulte, avec <span class=\"kw-clinique\">éviction</span> obl<span class=\"kw-chiffre\">iga</span>toire de la collectivité.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Quintes asphyxiantes</span>, <span class=\"kw-alerte\">cyanosantes</span>, <span class=\"kw-alerte\">apnées</span> (au cours des quintes ou isolées) ± <span class=\"kw-clinique\">cyanose</span></li><li><span class=\"kw-alerte\">Bradycardie</span> ou <span class=\"kw-alerte\">tachycardie</span> (souvent &gt; <span class=\"kw-chiffre\">200/min</span>)</li><li><span class=\"kw-alerte\">Malaise grave</span>, <span class=\"kw-alerte\">troubles de conscience</span>, <span class=\"kw-alerte\">convulsions</span></li><li><span class=\"kw-alerte\">Déshydratation aiguë</span>, <span class=\"kw-alerte\">dénutrition</span>, <span class=\"kw-clinique\">météorisme abdominal</span></li><li><span class=\"kw-alerte\">Hyperlymphocytose</span> &gt; <span class=\"kw-chiffre\">50 000/mm³</span> — <span class=\"kw-def\">annonce</span> la <span class=\"kw-alerte\">coqueluche maligne</span></li><li><span class=\"kw-alerte\">Insuffisance respiratoire décompensée</span>, <span class=\"kw-clinique\">hypoxie réfractaire</span> (<span class=\"kw-alerte\">SDRA</span>)</li><li><span class=\"kw-alerte\">Défaillance multiviscérale</span> (rénale, cardiaque, neurologique)</li></ul>","principes":"<p>Objectif <span class=\"kw-def\">double</span> : réduire la <span class=\"kw-clinique\">contagiosité</span> et écourter <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">symptômes</span> (ce dernier effet seulement si traitement précoce).</p><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> curative</strong></p><ul><li><strong>1ʳᵉ intention :</strong> <span class=\"kw-ttt\">macrolide</span> — <span class=\"kw-ttt\">azithromycine</span> (<span class=\"kw-chiffre\">3 j</span>) ou <span class=\"kw-ttt\">clarithromycine</span> (<span class=\"kw-chiffre\">7 j</span>)</li><li><strong>2ᵉ intention</strong> (<span class=\"kw-ci\">allergie</span> / CI aux macrolides) : <span class=\"kw-ttt\">cotrimoxazole</span> (<span class=\"kw-chiffre\">7 j</span>)</li><li><span class=\"kw-ttt\">Azithromycine</span> et <span class=\"kw-ttt\">clarithromycine</span> : possibles pendant la <span class=\"kw-clinique\">grossesse</span> (quel qu’en soit le terme) et l’<span class=\"kw-clinique\">allaitement</span></li><li>Active sur <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">symptômes</span> seulement si débutée à la phase <span class=\"kw-clinique\">catarrhale</span> (<span class=\"kw-chiffre\">&lt; 3 semaines</span>)</li></ul><p><strong>Éviction de la collectivité</strong></p><ul><li>Sans <span class=\"kw-ttt\">antibiothérapie</span> : <span class=\"kw-chiffre\">21 jours</span></li><li>Sous <span class=\"kw-ttt\">azithromycine</span> : <span class=\"kw-chiffre\">3 jours</span></li><li>Sous <span class=\"kw-ttt\">clarithromycine</span> ou <span class=\"kw-ttt\">cotrimoxazole</span> : <span class=\"kw-chiffre\">5 jours</span></li></ul><p><strong><span class=\"kw-ttt\">Antibioprophylaxie</span> des sujets contacts</strong></p><ul><li>Même schéma que l’ATB curative, le plus précocement possible et au plus tard <span class=\"kw-chiffre\">&lt; 21 j</span> après le dernier contage</li><li>Indiquée aux seuls <span class=\"kw-etio\">sujets non protégés par la vaccination</span> : contacts proches non vaccinés (même toit, crèche), <span class=\"kw-alerte\">immunodéprimés</span>, <span class=\"kw-etio\">maladies respiratoires chroniques</span> (asthme, BPCO), <span class=\"kw-alerte\">nourrissons non/incomplètement vaccinés</span>, <span class=\"kw-alerte\">femmes enceintes</span></li><li>Sujets <span class=\"kw-clinique\">protégés</span> (pas de prophylaxie) : enfant ≤ <span class=\"kw-chiffre\">11 mois</span> avec <span class=\"kw-chiffre\">2 doses</span>, enfant &gt;<span class=\"kw-chiffre\"> 11 mois</span> avec <span class=\"kw-chiffre\">3 doses</span> dont la dernière &lt; <span class=\"kw-chiffre\">5 ans</span>, adolescent/adulte dont la dernière dose &lt; <span class=\"kw-chiffre\">5 ans</span></li><li><strong>Rattrapage vaccinal</strong> de l’entourage non protégé : n’empêche pas la maladie après contage, mais limite la diffusion ultérieure de la bactérie</li></ul><p><strong>À proscrire</strong></p><ul><li><span class=\"kw-ci\">Bêta-lactamines</span> : <span class=\"kw-alerte\">inefficaces</span> sur Bordetella pertussis</li><li><span class=\"kw-ci\">Antitussifs et fluidifiants bronchiques</span> : <span class=\"kw-alerte\">contre-indiqués chez le nourrisson</span></li><li><span class=\"kw-ci\">Kinésithérapie respiratoire</span> : non indiquée à la phase des quintes</li></ul><p><strong>Notification</strong></p><ul><li><span class=\"kw-alerte\">Pas de déclaration obligatoire</span></li><li>Cas groupés (<span class=\"kw-chiffre\">≥ 2</span>) en collectivité (crèche, école) → médecin inspecteur de santé publique de l’<span class=\"kw-def\">ARS</span></li><li>Cas groupés (<span class=\"kw-chiffre\">≥ 2</span>) nosocomiaux (maternité, hôpital, EHPAD) → <span class=\"kw-def\">CLIN</span> + <span class=\"kw-def\">ARS</span></li></ul>","suivi":"<p><span class=\"kw-def\">Surveillance</span> rapprochée du <span class=\"kw-alerte\">nourrisson hospitalisé</span>, centrée sur la tolérance des quintes et le <span class=\"kw-def\">dépistage</span> des complications.</p><ul><li><span class=\"kw-def\">Isolement</span> respiratoire type <span class=\"kw-clinique\">« gouttelettes »</span> (chambre individuelle, masque chirurgical)</li><li><span class=\"kw-ttt\">Monitoring</span> par scope cardiorespiratoire continu</li><li><span class=\"kw-ttt\">Masque à oxygène</span> et <span class=\"kw-ttt\">ballon de ventilation</span> disponibles et opérationnels dans la chambre</li><li>Appréciation régulière des paramètres vitaux et de la tolérance des signes : <span class=\"kw-clinique\">quintes</span>, <span class=\"kw-alerte\">apnées</span>, <span class=\"kw-alerte\">cyanose</span>, <span class=\"kw-alerte\">bradycardie</span></li><li>Maintien de l’<span class=\"kw-clinique\">hydratation</span> et de l’état <span class=\"kw-clinique\">nutritionnel</span> : alimentation fractionnée ou <span class=\"kw-ttt\">nutrition entérale à débit constant</span> (NEDC)</li><li><span class=\"kw-def\">Dépistage</span> des complications : <span class=\"kw-bio\">NFS</span> (<span class=\"kw-def\">suivi</span> de l’<span class=\"kw-bio\">hyperlymphocytose</span>), recherche de <span class=\"kw-etio\">surinfection</span> si apparition d’une <span class=\"kw-alerte\">fièvre</span></li></ul>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf","label":"Collège Pilly — Coqueluche (item 163, PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Coqueluche confirmée — Cas index + sujets contacts de l’entourage","detail":"<h4>CAT — Coqueluche confirmée — Traiter le cas index puis prendre en charge l’entourage</h4>","branches":[{"to":"q-terrain","label":"Cas index (sujet malade)","color":"blue"},{"to":"q-protection","label":"Sujet contact","color":"blue"}]},{"id":"q-terrain","kind":"decision","label":"Cas index — terrain et gravité ?","branches":[{"to":"q-gravite","label":"Nourrisson < 3 mois ou signe de gravité","color":"red"},{"to":"q-allergie","label":"Grand enfant / adulte sans gravité","color":"green"}]},{"id":"q-gravite","kind":"decision","label":"Forme maligne ?","branches":[{"to":"t-rea","label":"Forme maligne / hyperlymphocytose > 50 000/mm³","color":"red"},{"to":"t-hospit","label":"Gravité sans forme maligne","color":"amber"}]},{"id":"t-rea","kind":"terminal","label":"Réanimation","color":"red","detail":"<h4>Conduite</h4><ul><li>Prise en charge en <span class=\"kw-ttt\">réanimation</span> (peut nécessiter <span class=\"kw-ttt\">échanges transfusionnels</span>, voire <span class=\"kw-ttt\">ECMO</span>). Transfert <strong>avant</strong> l’aggravation respiratoire.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Macrolide</span> (<span class=\"kw-ttt\">azithromycine</span> ou <span class=\"kw-ttt\">clarithromycine</span>) ; <span class=\"kw-ttt\">cotrimoxazole</span> si <span class=\"kw-ci\">allergie</span>. Support : <span class=\"kw-ttt\">monitoring</span> cardiorespiratoire, <span class=\"kw-ttt\">oxygène</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Hyperlymphocytose</span> &gt; <span class=\"kw-chiffre\">50 000/mm³</span> annonçant la <span class=\"kw-alerte\">forme maligne</span></li><li><span class=\"kw-alerte\">Insuffisance respiratoire</span> / hypoxie réfractaire (<span class=\"kw-alerte\">SDRA</span>), <span class=\"kw-clinique\">tachycardie</span> &gt; <span class=\"kw-chiffre\">200/min</span></li><li><span class=\"kw-alerte\">Défaillance multiviscérale</span> (rénale, cardiaque, neurologique)</li></ul>"},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation (pédiatrie / USC)","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Nourrisson &lt; 3 mois</span> → pédiatrie ; <span class=\"kw-alerte\">signes cliniques de gravité</span> → unité de <span class=\"kw-def\">surveillance</span> continue ou <span class=\"kw-alerte\">réanimation</span>. <span class=\"kw-def\">Isolement</span> <span class=\"kw-clinique\">« gouttelettes »</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Macrolide</span> : <span class=\"kw-ttt\">azithromycine</span> (<span class=\"kw-chiffre\">3 j</span>) ou <span class=\"kw-ttt\">clarithromycine</span> (<span class=\"kw-chiffre\">7 j</span>) ; <span class=\"kw-ttt\">cotrimoxazole</span> (<span class=\"kw-chiffre\">7 j</span>) si <span class=\"kw-ci\">allergie</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">Monitoring</span> par scope cardiorespiratoire</li><li>Tolérance des <span class=\"kw-clinique\">quintes</span>, <span class=\"kw-alerte\">apnées</span>, <span class=\"kw-alerte\">cyanose</span>, <span class=\"kw-alerte\">bradycardie</span></li><li>Maintien <span class=\"kw-clinique\">hydratation</span> / <span class=\"kw-clinique\">nutrition</span> (alimentation fractionnée ou <span class=\"kw-ttt\">NEDC</span>)</li></ul><h4>À proscrire</h4><ul><li><span class=\"kw-ci\">Antitussifs et fluidifiants bronchiques</span></li><li><span class=\"kw-ci\">Kinésithérapie respiratoire</span> à la phase des quintes</li><li><span class=\"kw-ci\">Bêta-lactamines</span> (inefficaces)</li></ul>"},{"id":"q-allergie","kind":"decision","label":"Allergie aux macrolides ?","branches":[{"to":"t-macrolide","label":"Pas d’allergie aux macrolides","color":"green"},{"to":"t-cotrimoxazole","label":"Allergie / CI aux macrolides","color":"amber"}]},{"id":"t-macrolide","kind":"terminal","label":"Ambulatoire — macrolide","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Macrolide</span> en 1ʳᵉ intention : <span class=\"kw-ttt\">azithromycine</span> (<span class=\"kw-chiffre\">3 j</span>) ou <span class=\"kw-ttt\">clarithromycine</span> (<span class=\"kw-chiffre\">7 j</span>). Possible pendant <span class=\"kw-clinique\">grossesse</span> et <span class=\"kw-clinique\">allaitement</span>.</li></ul><h4>Éviction</h4><ul><li><span class=\"kw-clinique\">Éviction</span> obl<span class=\"kw-chiffre\">iga</span>toire de la collectivité : <span class=\"kw-chiffre\">3 j</span> sous <span class=\"kw-ttt\">azithromycine</span>, <span class=\"kw-chiffre\">5 j</span> sous <span class=\"kw-ttt\">clarithromycine</span>, <span class=\"kw-chiffre\">21 j</span> en l’absence d’<span class=\"kw-ttt\">antibiothérapie</span>.</li></ul><h4>Conduite</h4><ul><li>Notifier <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">cas groupés</span> (<span class=\"kw-chiffre\">≥ 2</span>) à l’<span class=\"kw-def\">ARS</span> ± <span class=\"kw-def\">CLIN</span></li><li>Prendre en charge l’<strong>entourage</strong> (cf. branche « sujet <span class=\"kw-def\">contact</span> »)</li></ul>"},{"id":"t-cotrimoxazole","kind":"terminal","label":"Ambulatoire — cotrimoxazole","color":"amber","detail":"<h4>Traitement</h4><ul><li>En cas d’<span class=\"kw-ci\">allergie / CI aux macrolides</span> : <span class=\"kw-ttt\">cotrimoxazole</span> (<span class=\"kw-chiffre\">7 j</span>).</li></ul><h4>Éviction</h4><ul><li><span class=\"kw-clinique\">Éviction</span> de <span class=\"kw-chiffre\">5 j</span> sous <span class=\"kw-ttt\">cotrimoxazole</span>.</li></ul><h4>À proscrire</h4><ul><li><span class=\"kw-ci\">Bêta-lactamines</span> : inefficaces sur Bordetella pertussis.</li></ul>"},{"id":"q-protection","kind":"decision","label":"Contact protégé par la vaccination ?","branches":[{"to":"t-contact-protege","label":"Protégé par la vaccination (< 5 ans)","color":"green"},{"to":"t-prophylaxie","label":"Non protégé par la vaccination","color":"amber"}]},{"id":"t-contact-protege","kind":"terminal","label":"Sujet contact protégé","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-clinique\">Pas d’antibioprophylaxie</span>. Sont protégés : enfant ≤ <span class=\"kw-chiffre\">11 mois</span> avec <span class=\"kw-chiffre\">2 doses</span>, enfant &gt;<span class=\"kw-chiffre\"> 11 mois</span> avec <span class=\"kw-chiffre\">3 doses</span> dont la dernière &lt; <span class=\"kw-chiffre\">5 ans</span>, adolescent/adulte dont la dernière dose &lt; <span class=\"kw-chiffre\">5 ans</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Surveillance</span> clinique simple ; consulter en cas de <span class=\"kw-clinique\">toux</span> évocatrice.</li></ul>"},{"id":"t-prophylaxie","kind":"terminal","label":"Sujet contact non protégé","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibioprophylaxie</span> selon le <strong>même schéma</strong> que l’ATB curative (<span class=\"kw-ttt\">macrolide</span> ; <span class=\"kw-ttt\">cotrimoxazole</span> si <span class=\"kw-ci\">allergie</span>), le plus précocement possible, au plus tard <span class=\"kw-chiffre\">&lt; 21 j</span> après le dernier contage.</li></ul><h4>Conduite</h4><ul><li>Contacts proches non vaccinés (même toit, crèche)</li><li><span class=\"kw-alerte\">Immunodéprimés</span>, <span class=\"kw-etio\">maladies respiratoires chroniques</span> (asthme, BPCO)</li><li><span class=\"kw-alerte\">Nourrissons non/incomplètement vaccinés</span>, <span class=\"kw-alerte\">femmes enceintes</span></li><li><strong>Rattrapage vaccinal</strong> : n’empêche pas la maladie après contage mais limite la diffusion ultérieure</li></ul>"}]},"cards":[{"i":"0d0a1d4e2216","n":163,"o":"163-1","u":"Epidémiologie","t":"Connaître les caractéristiques épidémiologiques, la transmission de la coqueluche","q":"Quelle est la durée de l'immunité après une coqueluche ou une vaccination, et quelle est l'efficacité des anticorps maternels ?","a":"<div class=\"notion-course\"><p>L'immunité après une coqueluche n'est pas définitive et s'épuise en <strong>10 à 15 ans</strong> après la maladie naturelle. L'immunité vaccinale persiste environ <strong>5 à <span class=\"nc-pink nc-bold\">10 ans</span></strong> (retenir <strong>5 ans</strong> en QCM). Les anticorps maternels <strong>ne protègent pas</strong> le nourrisson, sauf en cas de <span class=\"nc-red nc-bold\">vaccination de la</span> mère pendant la grossesse.</p></div>"},{"i":"14e6198a3914","n":163,"o":"163-1","u":"Epidémiologie","t":"Connaître les caractéristiques épidémiologiques, la transmission de la coqueluche","q":"Quelle est la nature bactérienne et l'agent causal de la coqueluche ?","a":"<div class=\"notion-course\"><p>La coqueluche est une <strong><span class=\"nc-red nc-bold\">toxi-infection</span> bactérienne aiguë</strong> des voies aériennes, causée principalement par <em><strong><span class=\"nc-purple_bg nc-bold\">Bordetella pertussis</span></strong></em>, un bacille à Gram négatif. Une forme moins grave, la para-coqueluche, est due à <em><span class=\"nc-purple_bg\">Bordetella parapertussis</span></em>.</p></div>"},{"i":"8b6ff3ba8e8d","n":163,"o":"163-1","u":"Epidémiologie","t":"Connaître les caractéristiques épidémiologiques, la transmission de la coqueluche","q":"Quelle est la période de contagiosité de la coqueluche et le profil des populations réservoirs dans les pays industrialisés ?","a":"<div class=\"notion-course\"><p>La coqueluche est contagieuse <strong>jusqu'à 3 semaines après le début des signes</strong> sans antibiothérapie, et quasi nulle en <span class=\"nc-green_bg\">phase de convalescence</span>. Dans les pays industrialisés, le réservoir principal est constitué par les <strong><span class=\"nc-pink_bg nc-bold\">adultes</span> et les <span class=\"nc-pink_bg nc-bold\">personnes âgées</span></strong> dont la protection vaccinale a décliné, contaminant les <strong><span class=\"nc-red_bg\">nourrissons non vaccinés</span></strong> (principe du <strong>cocooning</strong>).</p></div>"},{"i":"d9874c92d204","n":163,"o":"163-1","u":"Epidémiologie","t":"Connaître les caractéristiques épidémiologiques, la transmission de la coqueluche","q":"Quelles sont les caractéristiques de la transmission de la coqueluche ?","a":"<div class=\"notion-course\"><p>La coqueluche est une maladie <strong>hautement contagieuse</strong>, à transmission <strong><span class=\"nc-blue nc-bold\">strictement interhumaine</span></strong>, par <strong><span class=\"nc-yellow_bg\">voie aérienne</span></strong> (aérosols, <span class=\"nc-yellow nc-bold\">gouttelettes</span>). Le <strong>taux d'attaque</strong> en cas de contact proche et répété est d'environ <strong>75%</strong>. La période d'<span class=\"nc-blue_bg\">incubation</span> est de <strong><span class=\"nc-pink_bg\">7 à 21 jours</span></strong> (moyenne de <span class=\"nc-pink nc-bold\">10 jours</span>).</p></div>"},{"i":"07c006d28084","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Quels sont les signes d'appel de la coqueluche chez l'adolescent ou l'adulte ?","a":"<div class=\"notion-course\"><p>Chez l'adolescent ou l'adulte, la coqueluche se présente comme une <strong><span class=\"nc-red nc-bold\">toux sans fièvre</span></strong>, persistant <strong><span class=\"nc-red nc-bold\">≥ 1 semaine</span></strong>, à <strong>recrudescence <span class=\"nc-red nc-bold\">nocturne</span></strong> et <span class=\"nc-red nc-bold\">insomniante</span>. Une notion de <strong><span class=\"nc-blue_bg\">contage</span></strong> et d'<span class=\"nc-blue_bg\">incubation</span> longue est fréquente. Des signes associés sont la <strong>toux <span class=\"nc-yellow_bg\">émétisante</span></strong> et un <span class=\"nc-blue_bg\">contage</span> identifié.</p></div>"},{"i":"2a0039f869af","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Quels sont les signes cliniques caractéristiques de la phase d'incubation et de la phase catarrhale de la coqueluche chez un grand enfant non vacciné ?","a":"<div class=\"notion-course\"><ul><li><strong>Phase d'<span class=\"nc-blue_bg\">incubation</span></strong> (<strong>7-21 jours</strong>) : cliniquement silencieuse.</li><li><strong>Phase <span class=\"nc-green nc-bold\">catarrhale</span></strong> (<strong>7-15 jours</strong>) : <span class=\"nc-green_bg nc-bold\">contagiosité</span> maximale, <span class=\"nc-brown_bg\">fièvre absente</span> ou modérée, <span class=\"nc-green_bg\">toux banale</span> puis tenace et quinteuse, <span class=\"nc-green_bg\">rhinorrhée</span>.</li></ul></div>"},{"i":"616b4e776296","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Comment se manifestent les quintes de toux durant la phase d'état de la coqueluche chez un grand enfant non vacciné ?","a":"<div class=\"notion-course\"><p>La phase d'état (<strong>3-6 <span class=\"nc-pink\">semaines</span></strong>) est caractérisée par des <strong><span class=\"nc-red nc-bold\">quintes</span> de toux violentes</strong> <span class=\"nc-red_bg\">sans inspiration efficace</span>, une congestion du visage voire une <strong><span class=\"nc-blue\">cyanose</span></strong>, une <span class=\"nc-green_bg\">reprise inspiratoire sonore</span> (« <strong>chant du coq</strong> »), et une <strong>toux <span class=\"nc-yellow_bg\">émétisante</span></strong>, à prédominance <span class=\"nc-red nc-bold\">nocturne</span>, déclenchée par la <span class=\"nc-red nc-bold\">déglutition</span>, les <span class=\"nc-red nc-bold\">cris</span> ou l'<span class=\"nc-red nc-bold\">effort</span>. Cette phase est <span class=\"nc-brown_bg\">sans fièvre</span>.</p></div>"},{"i":"7fed28e1926f","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Quand faut-il évoquer systématiquement la coqueluche chez un sujet non couvert par la vaccination ?","a":"<div class=\"notion-course\"><p>Il faut évoquer la coqueluche devant une <strong>toux <span class=\"nc-red nc-bold\">en l'absence de fièvre</span></strong>, prolongée <strong><span class=\"nc-pink nc-bold\">≥ 1 semaine</span></strong>, chez un sujet <span class=\"nc-red nc-bold\">non couvert par la vaccination</span>.</p></div>"},{"i":"f472fd9fae73","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Quelles sont les particularités cliniques de la coqueluche chez le nourrisson ?","a":"<div class=\"notion-course\"><p>Chez le nourrisson, la coqueluche se manifeste par des <strong><span class=\"nc-blue\">quintes asphyxiantes</span></strong>. La <span class=\"nc-green_bg\">reprise inspiratoire sonore</span> <span class=\"nc-red_bg nc-bold\">manque</span> généralement avant <strong>3 <span class=\"nc-pink\">mois</span></strong>. Il peut présenter des <strong><span class=\"nc-red nc-bold\">apnées</span></strong>, des <strong><span class=\"nc-red nc-bold\">bradycardies</span></strong> et des <strong><span class=\"nc-blue\">accès de cyanose</span></strong>. La coqueluche doit être évoquée devant toute toux quinteuse d'un nourrisson non vacciné.</p></div>"},{"i":"f8bea320413b","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Quelle est la principale orientation diagnostique pour la coqueluche ?","a":"<div class=\"notion-course\"><p>Le diagnostic de coqueluche est avant tout <strong>clinique</strong>.</p></div>"},{"i":"1648bc474190","n":163,"o":"163-4","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels de la coqueluche","q":"Quelle est l'importance de l'absence de fièvre dans le diagnostic différentiel de la coqueluche ?","a":"<div class=\"notion-course\"><p>L'absence de fièvre est une caractéristique importante car une fièvre n'appartient pas au tableau d'une <strong>coqueluche non compliquée</strong>. Sa présence doit faire <strong>reconsidérer le diagnostic</strong> de coqueluche ou évoquer une <strong>surinfection</strong>.</p></div>"},{"i":"643a574e1ec8","n":163,"o":"163-4","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels de la coqueluche","q":"Quels sont les diagnostics différentiels non infectieux, ORL et pneumo-allergologiques, d'une coqueluche atypique (toux subaiguë non fébrile) ?","a":"<div class=\"notion-course\"><p>Les diagnostics différentiels non infectieux ORL et pneumo-allergologiques, d'une toux subaiguë non fébrile sont :</p><ul><li><strong>ORL</strong> : sinusite chronique avec rhinorrhée postérieure.</li><li><strong>Pneumo-allergologique</strong> : asthme, allergie, pneumopathie interstitielle diffuse.</li></ul></div>"},{"i":"9d246d6ad4f0","n":163,"o":"163-4","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels de la coqueluche","q":"Quels sont les diagnostics différentiels infectieux à considérer chez un patient présentant une toux subaiguë non fébrile, évoquant une coqueluche ?","a":"<div class=\"notion-course\"><p>Devant une toux subaiguë non fébrile, les diagnostics différentiels infectieux à considérer, en dehors de la coqueluche, sont :</p><ul><li>Infections atypiques : <strong><em>Mycoplasma pneumoniae</em></strong>, <strong><em>Chlamydia pneumoniae</em></strong>.</li><li>Infections virales : <strong>grippe</strong>.</li><li>Autres infections bactériennes : <strong>tuberculose</strong>.</li></ul></div>"},{"i":"c34722555600","n":163,"o":"163-4","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels de la coqueluche","q":"Quels diagnostics différentiels mécaniques, iatrogènes ou psychogènes faut-il envisager devant une toux subaiguë non fébrile évoquant une coqueluche ?","a":"<div class=\"notion-course\"><p>Face à une toux subaiguë non fébrile, les diagnostics différentiels à envisager sont :</p><ul><li><strong>Mécaniques</strong> : RGO (reflux gastro-œsophagien), tumeur, compression trachéale, corps étranger.</li><li><strong>Iatrogènes</strong> : médicaments tels que les <strong>IEC</strong> (inhibiteurs de l'enzyme de conversion), <strong>bêta-bloquants</strong> (également ARA II, gliptines).</li><li><strong>Psychogènes</strong> : toux psychogène (diagnostic d'élimination).</li></ul></div>"},{"i":"049701669cb0","n":163,"o":"163-6","u":"Prise en charge","t":"Connaître les modalités de prescription de l’antibiothérapie","q":"Quel est l'impact de l'antibiothérapie sur les symptômes de la coqueluche selon le moment de son instauration ?","a":"<div class=\"notion-course\"><p>L'antibiothérapie est efficace pour écourter les symptômes de la coqueluche <strong>uniquement si elle est débutée précocement</strong>, lors de la <strong>phase <span class=\"nc-red nc-bold\">catarrhale</span></strong> (c'est-à-dire <strong>moins de 3 <span class=\"nc-pink\">semaines</span></strong> après le début des signes). Si elle est débutée à la phase des <span class=\"nc-red\">quintes</span>, elle est inefficace sur les symptômes, mais elle conserve son objectif de couper la <span class=\"nc-green_bg nc-bold\">contagiosité</span>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-red nc-bold\">Référence</span> HAS 2024 : clarithromycine privilégiée pour limiter l’impact écologique, azithromycine alternative. Choisir dose et durée selon âge ; nourrisson de moins de trois mois : évaluation hospitalière. Vérifier interactions, QT, grossesse et RCP plutôt que déclarer toute molécule interchangeable.</li></ul></div></div>"},{"i":"1e427d15a2b8","n":163,"o":"163-6","u":"Prise en charge","t":"Connaître les modalités de prescription de l’antibiothérapie","q":"Quels sont les traitements contre-indiqués ou inefficaces dans la prise en charge thérapeutique de la coqueluche ?","a":"<div class=\"notion-course\"><ul><li>Les <strong>bêta-lactamines</strong> sont <strong>inefficaces</strong> sur <em>Bordetella pertussis</em>.</li><li>Les <strong>antitussifs</strong> et <strong>fluidifiants bronchiques</strong> sont <strong>contre-indiqués chez le nourrisson</strong> et globalement à proscrire dans les infections respiratoires.</li><li>La <strong>kinésithérapie respiratoire</strong> n'est <strong>pas indiquée à la phase des <span class=\"nc-red\">quintes</span></strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-red nc-bold\">Référence</span> HAS 2024 : clarithromycine privilégiée pour limiter l’impact écologique, azithromycine alternative. Choisir dose et durée selon âge ; nourrisson de moins de trois mois : évaluation hospitalière. Vérifier interactions, QT, grossesse et RCP plutôt que déclarer toute molécule interchangeable.</li></ul></div></div>"},{"i":"2b332c794b0e","n":163,"o":"163-6","u":"Prise en charge","t":"Connaître les modalités de prescription de l’antibiothérapie","q":"Quel est le double objectif de l'antibiothérapie dans la coqueluche ?","a":"<div class=\"notion-course\"><p>L'antibiothérapie dans la coqueluche vise à :</p><ul><li><span class=\"nc-green_bg\">Réduire la</span> <strong><span class=\"nc-green_bg nc-bold\">contagiosité</span></strong>.</li><li>Écourter les <strong>symptômes</strong> si elle est débutée précocement.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-red nc-bold\">Référence</span> HAS 2024 : clarithromycine privilégiée pour limiter l’impact écologique, azithromycine alternative. Choisir dose et durée selon âge ; nourrisson de moins de trois mois : évaluation hospitalière. Vérifier interactions, QT, grossesse et RCP plutôt que déclarer toute molécule interchangeable.</li></ul></div></div>"},{"i":"42b8908562cd","n":163,"o":"163-6","u":"Prise en charge","t":"Connaître les modalités de prescription de l’antibiothérapie","q":"Quelles sont les molécules utilisées en première et deuxième intention pour l'antibiothérapie de la coqueluche, et leur durée de traitement ?","a":"<div class=\"notion-course\"><ul><li>En <strong>1ère intention</strong> : les <strong>macrolides</strong>, notamment l'<strong>azithromycine</strong> (pendant <strong><span class=\"nc-pink nc-bold\">3 jours</span></strong>) ou la <strong>clarithromycine</strong> (pendant <strong>7 jours</strong>).</li><li>En <strong>2ème intention</strong> (en cas de contre-indication ou d'allergie aux macrolides) : le <strong><span class=\"nc-pink_bg\">cotrimoxazole</span></strong> (pendant <strong>7 jours</strong>).</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-red nc-bold\">Référence</span> HAS 2024 : clarithromycine privilégiée pour limiter l’impact écologique, azithromycine alternative. Choisir dose et durée selon âge ; nourrisson de moins de trois mois : évaluation hospitalière. Vérifier interactions, QT, grossesse et RCP plutôt que déclarer toute molécule interchangeable.</li></ul></div></div>"},{"i":"4f7b1063ab96","n":163,"o":"163-6","u":"Prise en charge","t":"Connaître les modalités de prescription de l’antibiothérapie","q":"Les antibiotiques de première intention contre la coqueluche sont-ils utilisables chez la femme enceinte ou allaitante ?","a":"<div class=\"notion-course\"><p>Oui, l'<strong>azithromycine</strong> et la <strong>clarithromycine</strong> sont utilisables pendant la <strong>grossesse</strong> (quel qu'en soit le terme) et pendant l'<strong>allaitement</strong>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-red nc-bold\">Référence</span> HAS 2024 : clarithromycine privilégiée pour limiter l’impact écologique, azithromycine alternative. Choisir dose et durée selon âge ; nourrisson de moins de trois mois : évaluation hospitalière. Vérifier interactions, QT, grossesse et RCP plutôt que déclarer toute molécule interchangeable.</li></ul></div></div>"},{"i":"169730faea66","n":163,"o":"163-7","u":"Prise en charge","t":"Connaître les règles d’éviction de l’entourage et de la collectivité","q":"Quelle est la durée d'éviction d'une collectivité pour un patient atteint de coqueluche non traité par antibiotiques ?","a":"<div class=\"notion-course\"><p>En cas de coqueluche sans antibiothérapie, la durée d'éviction obligatoire de la collectivité est de <strong><span class=\"nc-pink nc-bold\">21 jours</span></strong>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Évaluer prophylaxie selon proximité, délai, protection et vulnérabilité, particulièrement nourrisson/entourage. Le délai depuis le dernier contact et les recommandations en contexte épidémique priment sur une règle simplifiée « uniquement non-vaccinés ».</li></ul></div></div>"},{"i":"34e529e1152b","n":163,"o":"163-7","u":"Prise en charge","t":"Connaître les règles d’éviction de l’entourage et de la collectivité","q":"Quelle est la durée d'éviction d'une collectivité pour un patient atteint de coqueluche sous traitement antibiotique par clarithromycine ou cotrimoxazole ?","a":"<div class=\"notion-course\"><p>Pour un patient atteint de coqueluche traité par <strong><span class=\"nc-pink_bg\">clarithromycine</span></strong> ou <strong><span class=\"nc-pink_bg\">cotrimoxazole</span></strong>, la durée d'éviction de la collectivité est de <strong><span class=\"nc-pink nc-bold\">5 jours</span></strong>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Évaluer prophylaxie selon proximité, délai, protection et vulnérabilité, particulièrement nourrisson/entourage. Le délai depuis le dernier contact et les recommandations en contexte épidémique priment sur une règle simplifiée « uniquement non-vaccinés ».</li></ul></div></div>"},{"i":"7de841bd97f0","n":163,"o":"163-7","u":"Prise en charge","t":"Connaître les règles d’éviction de l’entourage et de la collectivité","q":"Quels sont les sujets contacts dits 'à risque' qui doivent recevoir une antibioprophylaxie en cas de contact avec un cas de coqueluche ?","a":"<div class=\"notion-course\"><p>Les sujets contacts \"à risque\" devant bénéficier d'une antibioprophylaxie (s'ils ne sont pas protégés par la vaccination) sont :</p><ul><li>les <strong>personnes vivant sous le même toit</strong> et les <span class=\"nc-pink_bg nc-bold\">enfants</span>/personnels de crèche (considérés comme <span class=\"nc-red_bg\">contacts proches non vaccinés</span>),</li><li>les <strong>immunodéprimés</strong>,</li><li>les patients atteints de <strong><span class=\"nc-red_bg\">maladies respiratoires chroniques</span></strong> (asthme, BPCO),</li><li>les <strong>nourrissons non/incomplètement vaccinés</strong>,</li><li>les <strong><span class=\"nc-red_bg\">femmes enceintes</span></strong>,</li><li>l'<strong><span class=\"nc-red_bg\">entourage de nourrissons non encore vaccinés</span></strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Évaluer prophylaxie selon proximité, délai, protection et vulnérabilité, particulièrement nourrisson/entourage. Le délai depuis le dernier contact et les recommandations en contexte épidémique priment sur une règle simplifiée « uniquement non-vaccinés ».</li></ul></div></div>"},{"i":"a52500d031b2","n":163,"o":"163-7","u":"Prise en charge","t":"Connaître les règles d’éviction de l’entourage et de la collectivité","q":"Quels sont les critères de protection par la vaccination contre la coqueluche qui dispensent d'une antibioprophylaxie post-exposition ?","a":"<div class=\"notion-course\"><p>Sont considérés comme protégés (et ne nécessitent donc pas d'antibioprophylaxie) :</p><ul><li>les <strong>enfants de moins de 11 mois</strong> ayant reçu <strong>2 doses</strong> de vaccin,</li><li>les <strong>enfants de plus de 11 mois</strong> ayant reçu <strong>3 doses</strong> de vaccin dont la dernière remonte à <strong>moins de 5 ans</strong>,</li><li>les <strong>adolescents et adultes</strong> dont la dernière dose de vaccin remonte à <strong>moins de 5 ans</strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Évaluer prophylaxie selon proximité, délai, protection et vulnérabilité, particulièrement nourrisson/entourage. Le délai depuis le dernier contact et les recommandations en contexte épidémique priment sur une règle simplifiée « uniquement non-vaccinés ».</li></ul></div></div>"},{"i":"c3fd534a98e3","n":163,"o":"163-7","u":"Prise en charge","t":"Connaître les règles d’éviction de l’entourage et de la collectivité","q":"Quelle est la durée d'éviction d'une collectivité pour un patient atteint de coqueluche sous traitement antibiotique par azithromycine ?","a":"<div class=\"notion-course\"><p>Pour un patient atteint de coqueluche traité par <strong><span class=\"nc-pink_bg\">azithromycine</span></strong>, la durée d'éviction de la collectivité est de <strong><span class=\"nc-pink nc-bold\">3 jours</span></strong>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Évaluer prophylaxie selon proximité, délai, protection et vulnérabilité, particulièrement nourrisson/entourage. Le délai depuis le dernier contact et les recommandations en contexte épidémique priment sur une règle simplifiée « uniquement non-vaccinés ».</li></ul></div></div>"},{"i":"07a9f5cf313b","n":163,"o":"163-8","u":"Prise en charge","t":"Connaître les modalités de notification","q":"Quelles sont les modalités de notification des cas groupés de coqueluche en établissement de santé ou médico-social (hôpital, maternité, EHPAD) ?","a":"<div class=\"notion-course\"><p>Pour <strong>≥ 2 cas groupés</strong> en établissement de santé ou médico-social, la notification est requise auprès du <strong><span class=\"nc-red nc-bold\">CLIN</span></strong> (Comité de Lutte contre les Infections Nosocomiales) et du <strong>médecin inspecteur de santé publique de l'<span class=\"nc-red nc-bold\">ARS</span></strong>.</p></div>"},{"i":"2eba5f67c4a6","n":163,"o":"163-8","u":"Prise en charge","t":"Connaître les modalités de notification","q":"Quelles sont les modalités de notification des cas groupés de coqueluche en collectivité (crèche, école) ?","a":"<div class=\"notion-course\"><p>Pour <strong>≥ 2 cas groupés</strong> en collectivité (crèche, école), la notification est requise auprès du <strong>médecin inspecteur de santé publique de l'<span class=\"nc-red nc-bold\">ARS</span></strong>.</p></div>"},{"i":"afe7866fc8d4","n":163,"o":"163-8","u":"Prise en charge","t":"Connaître les modalités de notification","q":"Dans quel contexte la coqueluche nécessite-t-elle une notification particulière ?","a":"<div class=\"notion-course\"><p>La coqueluche nécessite une notification en cas de <strong>survenue de cas groupés</strong>.</p></div>"},{"i":"d6cf7cccc612","n":163,"o":"163-8","u":"Prise en charge","t":"Connaître les modalités de notification","q":"La coqueluche est-elle une maladie à déclaration obligatoire en France ?","a":"<div class=\"notion-course\"><p>Non, la coqueluche <strong>n'est pas une maladie à déclaration obligatoire</strong> en France.</p></div>"},{"i":"1ebe55d624cd","n":163,"o":"163-9","u":"Prise en charge","t":"Connaître les recommandations vaccinales","q":"En quoi consiste la stratégie de cocooning pour la vaccination contre la coqueluche ?","a":"<div class=\"notion-course\"><ul><li>Si vaccination maternelle absente ou trop proche de la naissance, cocooning de l’entourage selon calendrier. Les recommandations renforcées depuis 2024 concernent aussi les professionnels au contact de jeunes nourrissons ; vérifier le délai depuis le dernier rappel.</li><li>Ne pas appliquer une fréquence universelle « tous les dix ans » à toute situation de cocooning. Vacciner après exposition ne remplace pas l’antibioprophylaxie lorsqu’elle est indiquée.</li></ul></div>"},{"i":"34cce8914225","n":163,"o":"163-9","u":"Prise en charge","t":"Connaître les recommandations vaccinales","q":"Quelle est la particularité des doses antigéniques du vaccin coqueluche en fonction de l'âge ?","a":"<div class=\"notion-course\"><p>La dose d'antigène du vaccin coqueluche est <strong>forte chez l'enfant</strong> pour la primovaccination et les premiers rappels, puis elle est <strong>réduite</strong> (ca) pour les rappels à partir de <strong>11 ans</strong>.</p></div>"},{"i":"549f852e8d61","n":163,"o":"163-9","u":"Prise en charge","t":"Connaître les recommandations vaccinales","q":"Quel est le calendrier de vaccination et des rappels contre la coqueluche en France ?","a":"<div class=\"notion-course\"><ul><li>Vaccin acellulaire combiné : 2, 4, 11 mois, rappels à 6 ans et 11–13 ans. En 2026, rappels dTcaP à 25, 45, 65 ans puis tous les dix ans : la valence coqueluche est systématiquement associée aux rappels DTP en raison de l’indisponibilité du dTP seul.</li></ul></div>"},{"i":"852a7afb54e0","n":163,"o":"163-9","u":"Prise en charge","t":"Connaître les recommandations vaccinales","q":"Quelle est la nature du vaccin utilisé contre la coqueluche ?","a":"<div class=\"notion-course\"><p>La vaccination contre la coqueluche utilise un <strong>vaccin acellulaire</strong>, qui est <span class=\"nc-green_bg\">inactivé</span> et contient plusieurs antigènes purifiés de <em>Bordetella pertussis</em>.</p></div>"},{"i":"d0e0ab858b14","n":163,"o":"163-9","u":"Prise en charge","t":"Connaître les recommandations vaccinales","q":"Quelle est la recommandation actuelle de la HAS concernant la vaccination anti-coquelucheuse chez la femme enceinte ?","a":"<div class=\"notion-course\"><ul><li>Vaccination à chaque grossesse dès le deuxième trimestre, préférentiellement 20–36 SA, pour protéger le nourrisson par anticorps maternels.</li></ul></div>"},{"i":"f684210ab691","n":163,"o":"163-2","u":"Physiopathologie","t":"Connaître les mécanismes de la coqueluche","q":"Quels sont les points essentiels concernant les mécanismes de la coqueluche ?","a":"<div class=\"notion-course\"><p>La coqueluche est une <span><span class=\"nc-red nc-bold\">toxi-infection</span></span> : <span>Bordetella pertussis</span> sécrète plusieurs <span><span class=\"nc-pink nc-bold\">toxines</span></span> qui agissent sur l'<span><span class=\"nc-purple_bg\">épithélium trachéobronchique</span></span>. La bactérie reste localisée à la muqueuse respiratoire — ce sont ses <strong><span class=\"nc-pink nc-bold\">toxines</span></strong> qui font la maladie.</p>\n      <table>\n        <thead><tr><th>Facteur</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-pink_bg\">Hémagglutinine</span> <span class=\"nc-pink_bg\">filamenteuse</span></span></td><td><strong>Adhésine</strong> : permet l'interaction et la fixation de la bactérie à l'hôte</td></tr>\n          <tr><td><span><span class=\"nc-pink_bg\">Toxine</span> <span class=\"nc-pink_bg\">pertussique</span></span></td><td><span><span class=\"nc-red nc-bold\">Nécrose</span></span> de la muqueuse respiratoire ; <span><span class=\"nc-red nc-bold\">hyperlymphocytose</span></span> ; <span><span class=\"nc-red nc-bold\">hypersensibilité à l'histamine</span></span> ; tropisme neurologique</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"nc-purple nc-bold\">La </span><span><span class=\"nc-purple nc-bold\">toxine pertussique</span></span> stimule <span class=\"nc-red_bg\">la </span><strong><span class=\"nc-red_bg\">prolifération lymphocytaire</span></strong> : <span class=\"nc-red nc-bold\">l'</span><span><span class=\"nc-red nc-bold\">hyperlymphocytose</span></span> est donc évocatrice du diagnostic. Au-delà de <span>50 000/mm³</span>, elle devient un <span>critère de <span class=\"nc-red nc-bold\">gravité</span></span> qui <strong><span class=\"nc-red_bg nc-bold\">anticipe l'aggravation respiratoire</span></strong> (coqueluche maligne).</p>\n      <p>Après le <span>21ᵉ jour</span>, la bactérie a disparu mais <span>les</span> <span>symptômes persistent</span> : c'est le <strong>phénomène toxinique</strong> et l'<span>hyperréactivité bronchique</span> qui entretiennent la <span>toux</span>, alors que les prélèvements microbiologiques sont déjà négatifs.</p>\n      <div class=\"callout callout-info\"><strong>Conséquence pratique.</strong> Parce que la maladie est <span>toxinique</span>, l'<span>antibiothérapie</span> tardive n'agit plus sur <span>les</span> symptômes : elle ne fait que <span><span class=\"nc-green_bg\">réduire la</span> <span class=\"nc-green_bg nc-bold\">contagiosité</span></span>.</div></div>"},{"i":"7503e76614c3","n":163,"o":"163-5","u":"Examens complémentaires","t":"Connaître les modalités du diagnostic microbiologique","q":"Quels sont les points essentiels concernant les modalités du diagnostic microbiologique ?","a":"<div class=\"notion-course\"><p><strong>Examens non spécifiques</strong> — ils orientent sans confirmer :</p>\n      <ul>\n        <li><span>NFS</span> : <span><span class=\"nc-blue_bg\">hyperlymphocytose</span></span> (souvent &gt; <span>10 G/L</span>), inconstante dans <span>les</span> formes sans gravité.</li>\n        <li><span>Radiographie thoracique</span> : <span><span class=\"nc-green_bg nc-bold\">normale</span></span> ou simple <span class=\"nc-green_bg nc-bold\">syndrome bronchique</span> — réalisée surtout pour éliminer un <span>diagnostic différentiel</span>.</li>\n        <li><span>Pas de syndrome inflammatoire</span> <span>biologique</span>.</li>\n      </ul>\n      <p><strong>Confirmation microbiologique</strong> — sur <span>aspiration</span> ou <span>écouvillonnage nasopharyngé</span> (ou recueil de mucus de quinte) :</p>\n      <table>\n        <thead><tr><th>Technique</th><th>Performances</th><th>Place</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-blue_bg\">PCR Bordetella</span></span></td><td><strong><span class=\"nc-red nc-bold\">Référence</span></strong> : <span>90 %</span> de sensibilité, <span>99 %</span> de spécificité ; maximale la 1ʳᵉ semaine ; résultat en <span><span class=\"nc-pink nc-bold\">24 h</span></span></td><td>Examen de 1ʳᵉ intention</td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">Culture</span></span> (milieux <span><span class=\"nc-red nc-bold\">Bordet-Gengou</span></span> ou <span>Regan-Lowe</span>)</td><td>Spécificité <span>100 %</span> mais sensibilité <span>faible</span> ; à réaliser &lt; <span>15 j</span> ; résultat en 3-7 j</td><td>Surtout <span><span class=\"nc-blue nc-bold\">surveillance</span></span><span class=\"nc-blue nc-bold\"> épidémiologique</span> des souches</td></tr>\n          <tr><td><span>Sérologie</span></td><td>Sensibilité et spécificité insuffisantes</td><td><span>Non recommandée en France</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Choix de la technique selon le délai</strong> depuis le début des symptômes :</p>\n      <table>\n        <thead><tr><th>Délai</th><th>Inoculum <span>bactérien</span></th><th>Technique</th></tr></thead>\n        <tbody>\n          <tr><td>&lt; <span>15 jours</span></td><td>Élevé</td><td><span>PCR + culture</span> rentables</td></tr>\n          <tr><td><span>15-21 jours</span></td><td>Faible</td><td><span>PCR</span> uniquement</td></tr>\n          <tr><td>&gt; <span>21 jours</span></td><td>Bactéries disparues</td><td>Diagnostic <span>clinique</span> ; tests négatifs sur le cas index, <span>PCR/culture</span> encore utiles chez un cas <span>contact</span> récent</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span>négativation des prélèvements à J21</span> explique que l'<span>isolement</span> soit levé à cette date en l'absence d'<span>antibiothérapie</span>.</div></div>"},{"i":"aa09f056dee4","n":163,"o":"163-10","u":"Suivi et/ou pronostic","t":"Connaître les modalités du dépistage des complications de la coqueluche","q":"Quels sont les points essentiels concernant les modalités du dépistage des complications de la coqueluche ?","a":"<div class=\"notion-course\"><p><strong>Critères d'<span>hospitalisation</span></strong> : âge <span><span class=\"nc-pink nc-bold\">&lt; 3 mois</span></span> (toute suspicion) ; signes cliniques de <span class=\"nc-red nc-bold\">gravité</span> quel que soit l'âge (<span class=\"nc-yellow_bg\">unité de </span><span><span class=\"nc-yellow_bg\">surveillance</span></span><span class=\"nc-yellow_bg\"> continue</span> ou <span>réanimation</span>) ; formes malignes (réanimation).</p>\n      <p><strong>Complications du nourrisson</strong> (surtout &lt;<span> 3 mois</span>) :</p>\n      <table>\n        <thead><tr><th>Complication</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span>Coqueluche maligne</span></td><td>Responsable de la majorité des décès : <span><span class=\"nc-blue_bg\">hyperlymphocytose majeure</span></span> &gt; <span>50 000/mm³</span>, <span>insuffisance respiratoire</span> / <span class=\"nc-red_bg\">hypoxie réfractaire</span> (<span>SDRA</span>), <span><span class=\"nc-red_bg\">tachycardie</span></span> <span class=\"nc-pink nc-bold\">&gt; </span><span><span class=\"nc-pink nc-bold\">200/min</span></span>, <span><span class=\"nc-red_bg\">défaillance</span></span><span class=\"nc-red_bg\"> multiviscérale</span> → <span>réanimation</span>, <span class=\"nc-pink_bg\">échanges transfusionnels</span> voire <span><span class=\"nc-pink_bg\">ECMO</span></span></td></tr>\n          <tr><td><span>Encéphalopathie coquelucheuse</span></td><td>Exceptionnelle mais très sévère (1/3 décès, 1/3 <span class=\"nc-orange_bg\">séquelles</span>, 1/<span <span=\"\">&gt;3</span> guérison) : <span><span class=\"nc-orange_bg\">état de mal</span></span><span class=\"nc-orange_bg\"> convulsif</span>, troubles <span class=\"nc-blue_bg\">moteurs</span> et <span class=\"nc-blue_bg\">sensoriels</span></td></tr>\n          <tr><td>Respiratoires</td><td><span class=\"nc-orange_bg\">Broncho-pneumopathie</span> (surinfection) ; <span><span class=\"nc-red nc-bold\">atélectasie</span></span> ; <span><span class=\"nc-red nc-bold\">pneumothorax</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Complications de l'adolescent et de l'adulte</strong> :</p>\n      <table>\n        <thead><tr><th>Type</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td>Infectieuses</td><td><span class=\"nc-red nc-bold\">Surinfection </span><span><span class=\"nc-red nc-bold\">bactérienne</span></span> ou virale (otite, sinusite, <span>pneumonie</span>) — à suspecter si <span>fièvre</span></td></tr>\n          <tr><td>Neurologiques</td><td><span><span class=\"nc-red_bg\">Convulsions</span></span>, encéphalopathie (très rares)</td></tr>\n          <tr><td>Mécaniques</td><td><span><span class=\"nc-orange_bg\">Fractures de côtes</span></span> ; <span><span class=\"nc-blue_bg\">hémorragies sous-conjonctivales</span></span> ; <span><span class=\"nc-red_bg\">pneumothorax</span></span> ; <span class=\"nc-red_bg\">emphysème médiastinal</span> ; <span class=\"nc-blue_bg\">hernie</span> ; <span><span class=\"nc-blue_bg\">incontinence urinaire</span></span><span class=\"nc-blue_bg\"> transitoire</span> ; <span class=\"nc-blue_bg\">prolapsus</span></td></tr>\n          <tr><td>Générales</td><td><span class=\"nc-orange_bg\">Dénutrition</span> et <span><span class=\"nc-orange_bg\">déshydratation</span></span> (<span><span class=\"nc-blue\">vomissements</span></span>) ; <span><span class=\"nc-red_bg\">décompensation</span></span><span class=\"nc-red_bg\"> de </span><span><span class=\"nc-red_bg\">comorbidités</span></span> (<span>diabète</span>, <span>insuffisance respiratoire</span> ou cardiaque)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Signe d'alarme.</strong> Chez le nourrisson, une <span>hyperlymphocytose &gt; 50 000/mm³</span> <span>annonce</span> la <span>coqueluche maligne</span> et impose le transfert en <span>réanimation</span> <strong>avant</strong> l'aggravation respiratoire.</div></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d9418103b252f881dfe5e0d3?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
